//! Every counter in `counters.toml`, as constants: one [`CounterId`] per entry and the
//! [`COUNTERS`] table. Generated by `scripts/gen-counters.py`; do not edit. Change
//! `counters.toml` and run `just gen-counters`; `just lint-counters` fails while this
//! file is stale (ADR 0012).

use super::{CounterDef, CounterId, Kind, Scope};

/// `counters.allocated`, a static gauge: Metadata records in the allocated state, this counter's own record included.
pub const COUNTERS_ALLOCATED: CounterId = CounterId(0);

/// `counters.allocation_failed`, a static counter: Counter allocations refused because every record was in use: the counters file is full, and whatever needed the counter was refused with it.
pub const COUNTERS_ALLOCATION_FAILED: CounterId = CounterId(1);

/// `publication.position`, a instance gauge: The producer position of one publication's log buffer, written by the driver on its duty cycle from a load it makes at most once every two milliseconds, so at most two milliseconds behind the publisher (ADR 0022, ADR 0032); key: correlation id (i64), session id (i32), stream id (i32), little-endian; label text: the three in decimal, space-separated.
pub const PUBLICATION_POSITION: CounterId = CounterId(2);

/// `publication.limit`, a instance gauge: The position up to which one publication may write: the slowest subscriber's position plus the publication window, written by the driver; key and label as publication.position.
pub const PUBLICATION_LIMIT: CounterId = CounterId(3);

/// `subscription.position`, a instance gauge: How far one subscription has read one publication's stream, written by the subscriber after each poll with a release store; key: correlation id (i64), session id (i32), stream id (i32), little-endian; label text: the three in decimal, space-separated.
pub const SUBSCRIPTION_POSITION: CounterId = CounterId(4);

/// `publication.unblocked`, a static counter: Stale claims the driver turned into padding frames because a publisher claimed and did not commit within the unblock timeout (spec/log-buffer.md, The driver).
pub const PUBLICATION_UNBLOCKED: CounterId = CounterId(5);

/// `log_buffer.rejected_position`, a static counter: Subscriber positions the driver found outside the spec's bounds and refused to use; the client that wrote one is evicted (ADR 0010).
pub const LOG_BUFFER_REJECTED_POSITION: CounterId = CounterId(6);

/// `log_buffer.rejected_tail`, a static counter: Tail counters the driver found inconsistent with the active term count and refused to use; the publication is closed (ADR 0010).
pub const LOG_BUFFER_REJECTED_TAIL: CounterId = CounterId(7);

/// `log_buffer.rejected_frame`, a static counter: Frames a subscriber found outside spec/frame.md's bounds in a term and reported; nothing after such a frame is delivered on that image.
pub const LOG_BUFFER_REJECTED_FRAME: CounterId = CounterId(8);

/// `command_ring.unblocked`, a static counter: Padding records the driver wrote over a claim in the command ring that a client made and did not commit within the unblock timeout (spec/command-ring.md, Unblocking).
pub const COMMAND_RING_UNBLOCKED: CounterId = CounterId(9);

/// `command_ring.rejected_tail`, a static counter: Tail positions the driver found outside the command ring's bounds when it unblocked and refused to use (ADR 0010): the ring is corrupt and the driver reads nothing more from it (spec/command-ring.md, Unblocking).
pub const COMMAND_RING_REJECTED_TAIL: CounterId = CounterId(10);

/// `command_ring.rejected_record`, a static counter: Records the driver found outside the command ring's bounds, a length or type no client writes by the protocol (ADR 0010): the driver reads nothing more from the ring (spec/command-ring.md, Reading).
pub const COMMAND_RING_REJECTED_RECORD: CounterId = CounterId(11);

/// `client.timed_out`, a static counter: Clients the driver timed out because no command of theirs arrived within the client liveness timeout; their publications and subscriptions were removed and a client timeout event sent (spec/client-protocol.md, Liveness and timeouts).
pub const CLIENT_TIMED_OUT: CounterId = CounterId(12);

/// `client_protocol.rejected_command`, a static counter: Commands the driver refused at decoding, for their channel or for a field outside its bound: a message too short to carry a correlation id, an unknown type, a message of the wrong length, a bad string, a channel that is not cavalry:ipc, or a replay length below -1 (spec/client-protocol.md, What the driver rejects); the client got an error event when its correlation id was readable.
pub const CLIENT_PROTOCOL_REJECTED_COMMAND: CounterId = CounterId(13);

/// `client_protocol.errors`, a static counter: Error events the driver sent, whatever the code: every command this version refused after the ring delivered it (spec/client-protocol.md, Error codes); the causes with a counter of their own are client_protocol.rejected_command, driver.registry_full and driver.log_create_failed.
pub const CLIENT_PROTOCOL_ERRORS: CounterId = CounterId(14);

/// `driver.registry_full`, a static counter: Commands refused with error code 10 because the driver's registry of clients, publications, subscriptions or images, or the counters file, was at capacity (spec/client-protocol.md, Sizes).
pub const DRIVER_REGISTRY_FULL: CounterId = CounterId(15);

/// `driver.log_create_failed`, a static counter: Log buffers the driver could not create or size, refused with error code 12: the filesystem under the driver directory is full or not writable (spec/client-protocol.md, Commands).
pub const DRIVER_LOG_CREATE_FAILED: CounterId = CounterId(16);

/// `conductor.idle_strategy`, a static gauge: The idle strategy the conductor runs, what its thread does on a duty cycle that found no work, stored once when the driver starts: 0 backoff, 1 yield, 2 busy-spin.
pub const CONDUCTOR_IDLE_STRATEGY: CounterId = CounterId(17);

/// `counters.allocations`, a static counter: Counter allocations made since the driver started, the static counters' own records included: every record that went from unused or reclaimed to allocated, the transition counters.allocated adds one for, so that counters.allocations minus counters.freed is counters.allocated (spec/counters-file.md, Metadata record).
pub const COUNTERS_ALLOCATIONS: CounterId = CounterId(18);

/// `counters.freed`, a static counter: Counters freed since the driver started: every record that went from allocated to reclaimed, the transition counters.allocated loses one for; a reclaimed record is allocated again after the counter reuse timeout.
pub const COUNTERS_FREED: CounterId = CounterId(19);

/// `recording.started`, a static counter: Recordings the driver started: a catalog slot taken, the time index and the first segment file created, the two position counters allocated and recording ready sent (spec/client-protocol.md, Commands).
pub const RECORDING_STARTED: CounterId = CounterId(20);

/// `recording.stopped`, a static counter: Recordings the driver stopped, by stop recording, at a publication's end of stream, or after a failed write or a frame that failed its check; each sent recording stopped with the stop position (spec/client-protocol.md, Commands).
pub const RECORDING_STOPPED: CounterId = CounterId(21);

/// `recording.write_failed`, a static counter: Writes or syncs the recorder could not make to a recording's segment file or time index, each of which stopped the recording at the position written (spec/client-protocol.md, Commands).
pub const RECORDING_WRITE_FAILED: CounterId = CounterId(22);

/// `recording.start_failed`, a static counter: Start recording commands refused with error code 12 because the recording's time index or first segment file could not be created in the log directory (spec/client-protocol.md, Commands). The recording's catalog slot may already be taken: a start that fails at its files leaves its slot valid, stopped at the start position, so the catalog's slots used are at most recording.started plus these plus the driver.registry_full refusals of a start.
pub const RECORDING_START_FAILED: CounterId = CounterId(23);

/// `recording.catalog_full`, a static counter: Start recording commands refused with error code 10 because the catalog holds every one of its 1048576 slots (spec/durable-log.md, Catalog header).
pub const RECORDING_CATALOG_FULL: CounterId = CounterId(24);

/// `recording.recovered`, a static counter: Recordings found live, or with a torn stop, when the driver opened the log directory, whose stop fields recovery rebuilt from their files (spec/durable-log.md, The driver).
pub const RECORDING_RECOVERED: CounterId = CounterId(25);

/// `recording.invalidated`, a static counter: Catalog slots recovery set to state 2 because their files cannot repair them: an empty slot before the last, a creation checksum that fails, or a segment file missing between the start and the last (spec/durable-log.md, The driver).
pub const RECORDING_INVALIDATED: CounterId = CounterId(26);

/// `recording.index_rewritten`, a static counter: Time indexes recovery wrote again with their start entry, gave a first entry, or truncated to whole entries in order or to the entries at or before the rebuilt stop (spec/durable-log.md, The driver).
pub const RECORDING_INDEX_REWRITTEN: CounterId = CounterId(27);

/// `recording.catalog_truncated`, a static counter: Catalog files recovery truncated to whole slots because a crash left bytes past the last slot: 0 or 1 at each driver start (spec/durable-log.md, The driver).
pub const RECORDING_CATALOG_TRUNCATED: CounterId = CounterId(28);

/// `recording.slot_dropped`, a static counter: Empty last catalog slots recovery dropped because a crash tore a recording's creation: 0 or 1 at each driver start, and the next recording takes the id (spec/durable-log.md, The driver).
pub const RECORDING_SLOT_DROPPED: CounterId = CounterId(29);

/// `recording.files_removed`, a static counter: Files recovery removed: segment files wholly past a rebuilt stop, and the files of a deleted recording that were still present (spec/durable-log.md, The driver).
pub const RECORDING_FILES_REMOVED: CounterId = CounterId(30);

/// `recording.position`, a instance gauge: The position of one recording up to which the recorder has written its segment files, what the operating system holds, stored with a release store after each block; the publisher's limit respects it (spec/log-buffer.md, The driver); key: recording id (i64), little-endian; label text: the recording id, the session id and the stream id in decimal, space-separated.
pub const RECORDING_POSITION: CounterId = CounterId(31);

/// `recording.synced_position`, a instance gauge: The position of one recording up to which a sync has made its segment files and time index durable, stored with a release store after each sync, at most a second behind recording.position; key and label as recording.position.
pub const RECORDING_SYNCED_POSITION: CounterId = CounterId(32);

/// `replay.started`, a static counter: Replays the driver started: the replay's publication created at the start position, its counters allocated and replay ready sent (spec/client-protocol.md, Commands; ADR 0030).
pub const REPLAY_STARTED: CounterId = CounterId(33);

/// `replay.stopped`, a static counter: Replays that ended, for any reason: each sent replay stopped with the position reached and the reason; replay.ended, replay.not_connected and replay.failed count the reasons other than a stop replay command (spec/client-protocol.md, Commands).
pub const REPLAY_STOPPED: CounterId = CounterId(34);

/// `replay.ended`, a static counter: Replays that reached their end position or their recording's stop position, reason 0 of replay stopped: the subscriber saw everything it asked for.
pub const REPLAY_ENDED: CounterId = CounterId(35);

/// `replay.not_connected`, a static counter: Replays the driver ended, reason 2 of replay stopped, because their publication had no subscriber for the replay connect timeout, from the start or from the moment the last subscriber went (spec/client-protocol.md, Liveness and timeouts).
pub const REPLAY_NOT_CONNECTED: CounterId = CounterId(36);

/// `replay.failed`, a static counter: Replays that ended on a failure, reason 3 of replay stopped: a segment file of the recording could not be read, or a frame in it failed a check, which log_buffer.rejected_frame counts as well; the position in the event is the last frame delivered.
pub const REPLAY_FAILED: CounterId = CounterId(37);

/// `replay.start_failed`, a static counter: Start replay commands refused after the driver took them, with error code 21 (a recording id the catalog does not hold as a valid recording), 24 (a recording a truncate recording, purge segments or purge recording is working on), 23 (a position out of range) or 12 (a segment file that could not be opened); a start the registries refuse with code 10 is driver.registry_full's, and a replay log that could not be created is driver.log_create_failed's (spec/client-protocol.md, Commands; ADR 0031).
pub const REPLAY_START_FAILED: CounterId = CounterId(38);

/// `replay.position`, a instance gauge: The position of one replay up to which the replayer has written the recording's frames into the replay's log, stored with a release store after each block; it moves no faster than the slowest subscriber's position plus the publication window, and not at all with no subscriber (spec/client-protocol.md, Commands); key: replay session id (i64), little-endian; label text: the replay session id, the recording id, the replay publication's session id and its stream id in decimal, space-separated.
pub const REPLAY_POSITION: CounterId = CounterId(39);

/// `recording.truncated`, a static counter: Stopped recordings truncated to a position by `truncate recording`: the segment files past the position removed, the one holding it cut, the time index shortened and the stop written again (spec/client-protocol.md, Commands; ADR 0031).
pub const RECORDING_TRUNCATED: CounterId = CounterId(40);

/// `recording.segments_purged`, a static counter: Segment files removed by `purge segments`, one per file, once the recording's retained position was written past them (spec/durable-log.md, The driver; ADR 0031).
pub const RECORDING_SEGMENTS_PURGED: CounterId = CounterId(41);

/// `recording.deleted`, a static counter: Stopped recordings deleted by `purge recording`: the slot's state written as 3, then the segment files and the time index removed; the slot stays, so the id never names another recording (ADR 0024, ADR 0031).
pub const RECORDING_DELETED: CounterId = CounterId(42);

/// `recording.retention_failed`, a static counter: Retention commands the files refused with error code 12: a segment file the replayer could not open or read for a truncate's frame check before the catalog write, or a file it could not remove, cut or extend after it, when the driver ran recovery's rule for the slot at once so that the slot and the files agree (spec/client-protocol.md, Commands; ADR 0031).
pub const RECORDING_RETENTION_FAILED: CounterId = CounterId(43);

/// `recording.bytes`, a instance gauge: The bytes one live recording's segment files take on disk, the segment file length times the files present, kept by the recorder at each roll and stored with a release store; key and label as recording.position; freed with it after the stop, after which `cavalry doctor` computes a stopped recording's bytes from its descriptor (ADR 0031).
pub const RECORDING_BYTES: CounterId = CounterId(44);

